create extension if not exists pgcrypto;
do $$ begin create type public.peran_pengguna as enum ('editor','admin','superadmin'); exception when duplicate_object then null; end $$;
create table if not exists public.pengguna(id uuid primary key references auth.users(id) on delete cascade,nama text not null default '',peran public.peran_pengguna not null default 'editor',aktif boolean not null default true,dibuat_pada timestamptz not null default now(),diperbarui_pada timestamptz not null default now());
create table if not exists public.berita(id uuid primary key default gen_random_uuid(),judul text not null,slug text unique not null,kategori text not null default 'Kegiatan',ringkasan text not null default '',isi text not null,url_gambar text,id_publik_gambar text,status text not null default 'draf' check(status in('draf','terbit','arsip')),pembuat_id uuid references auth.users(id),tanggal_terbit timestamptz,dibuat_pada timestamptz not null default now(),diperbarui_pada timestamptz not null default now());
create table if not exists public.relawan(id uuid primary key default gen_random_uuid(),pengguna_id uuid references auth.users(id),nama text not null,nik text unique,jenis_kelamin text,alamat text,telepon text,email text,jenis_keanggotaan text not null check(jenis_keanggotaan in('PMR Mula','PMR Madya','PMR Wira','KSR','TSR')),asal text,status text not null default 'Menunggu Verifikasi',dibuat_pada timestamptz not null default now(),diperbarui_pada timestamptz not null default now());
create table if not exists public.agenda(id uuid primary key default gen_random_uuid(),judul text not null,lokasi text not null default '',deskripsi text not null default '',mulai_pada timestamptz not null,selesai_pada timestamptz,status text not null default 'terjadwal',dibuat_pada timestamptz not null default now());
create table if not exists public.galeri(id uuid primary key default gen_random_uuid(),judul text not null,url_gambar text not null,id_publik_gambar text not null,kategori text not null default 'Kegiatan',tampil boolean not null default true,dibuat_pada timestamptz not null default now());
create index if not exists idx_berita_status_tanggal on public.berita(status,tanggal_terbit desc);create index if not exists idx_relawan_jenis on public.relawan(jenis_keanggotaan);create index if not exists idx_agenda_mulai on public.agenda(mulai_pada);